CREATE OR REPLACE FUNCTION public.enforce_budget_request_purpose_advocacy()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _advocacies text[];
  _org_seeded boolean;
  _org_seed_batch text;
  _org_is_renewal boolean;
  _category_changed boolean;
  _canonical_category text;
BEGIN
  SELECT op.advocacies,
         coalesce(op.is_seeded_sample_data, false),
         op.seed_batch,
         coalesce(op.is_renewal_test_account, false)
  INTO _advocacies, _org_seeded, _org_seed_batch, _org_is_renewal
  FROM public.organization_profiles op
  WHERE op.id = NEW.organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Budget request organization profile was not found.';
  END IF;

  _category_changed := TG_OP = 'INSERT'
    OR lower(trim(coalesce(NEW.purpose_category, ''))) IS DISTINCT FROM lower(trim(coalesce(OLD.purpose_category, '')))
    OR NEW.organization_id IS DISTINCT FROM OLD.organization_id;

  IF NOT _category_changed THEN
    RETURN NEW;
  END IF;

  IF cardinality(coalesce(_advocacies, ARRAY[]::text[])) = 0 THEN
    RAISE EXCEPTION 'Select at least one Center of Youth Participation in the organization profile before creating or changing a budget request category.';
  END IF;

  SELECT cyp
  INTO _canonical_category
  FROM unnest(_advocacies) AS cyp
  WHERE lower(trim(cyp)) = lower(trim(coalesce(NEW.purpose_category, '')))
  LIMIT 1;

  IF _canonical_category IS NOT NULL THEN
    NEW.purpose_category := _canonical_category;
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT'
     AND NEW.is_seeded_sample_data IS TRUE
     AND NEW.seed_batch = 'PCYDO-YORP-2024-2026'
     AND _org_seeded IS TRUE
     AND _org_seed_batch = 'PCYDO-YORP-2024-2026'
     AND _org_is_renewal IS FALSE THEN
    NEW.purpose_category := public.resolve_yorp_seed_budget_category(NEW.purpose_category, _advocacies);
    IF NEW.purpose_category IS NOT NULL THEN
      RETURN NEW;
    END IF;
  END IF;

  RAISE EXCEPTION 'Purpose & Category must match a Center of Youth Participation selected in the organization profile.';
END;
$function$

CREATE OR REPLACE FUNCTION public.notify_budget_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  org_user_id uuid;
  notif_type public.notification_type;
  notif_title text;
  notif_message text;
BEGIN
  SELECT op.user_id INTO org_user_id
  FROM public.organization_profiles op
  WHERE op.id = new.organization_id;

  IF new.status IN ('approved_for_ftf_green', 'budget_released') THEN
    notif_type := CASE WHEN new.status = 'budget_released' THEN 'budget_released' ELSE 'budget_go_signal' END;
    notif_title := CASE WHEN new.status = 'budget_released' THEN 'Budget released' ELSE 'Budget go signal issued' END;
    notif_message := CASE
      WHEN new.status = 'budget_released' THEN 'Your budget has been released.'
      ELSE 'Your soft copy requirements have been pre-checked. You may now submit the hard copies face-to-face.'
    END;

    INSERT INTO public.notifications (user_id, organization_id, title, message, type, related_type, related_id)
    VALUES (org_user_id, new.organization_id, notif_title, notif_message, notif_type, 'budget_request', new.id);
  ELSIF new.status = 'needs_revision' THEN
    INSERT INTO public.notifications (user_id, organization_id, title, message, type, related_type, related_id)
    VALUES (org_user_id, new.organization_id, 'Budget revision requested', 'Your budget request has been marked needs revision.', 'budget_revision', 'budget_request', new.id);
  ELSIF new.status = 'rejected_red' THEN
    INSERT INTO public.notifications (user_id, organization_id, title, message, type, related_type, related_id)
    VALUES (org_user_id, new.organization_id, 'Budget request rejected', 'Your budget request has been marked rejected.', 'document_red', 'budget_request', new.id);
  END IF;

  INSERT INTO public.activity_logs (actor_user_id, organization_id, action, related_type, related_id, description)
  VALUES (NULL, new.organization_id, 'reviewed_budget_request', 'budget_request', new.id, COALESCE(new.remarks, 'Budget request status changed.'));

  RETURN new;
END;
$function$

