CREATE OR REPLACE FUNCTION public.enforce_budget_request_resubmission_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _revision_at timestamptz;
BEGIN
  IF NEW.status = 'needs_revision' AND OLD.status IS DISTINCT FROM NEW.status THEN
    NEW.revision_requested_at := clock_timestamp();
    NEW.revision_due_at := NEW.revision_requested_at + interval '5 days';
  END IF;

  IF OLD.status = 'needs_revision' AND NEW.status IS DISTINCT FROM OLD.status
     AND NEW.status IN ('submitted', 'under_review', 'awaiting_release', 'approved_for_ftf_green', 'hard_copy_submitted', 'budget_released', 'completed') THEN
    IF NEW.status <> 'submitted' THEN
      RAISE EXCEPTION 'Resubmission required: submit the revised budget proposal for review before approval.';
    END IF;
    -- Legacy rows without a revision timestamp fail closed against the last update.
    _revision_at := COALESCE(OLD.revision_requested_at, OLD.updated_at);
    IF _revision_at IS NULL OR NOT EXISTS (
      SELECT 1 FROM public.budget_request_files f
      WHERE f.budget_request_id = OLD.id AND f.uploaded_at > _revision_at
        AND COALESCE(f.admin_status, '') NOT IN ('needs_revision', 'rejected_red')
    ) THEN
      RAISE EXCEPTION 'A new replacement proposal file is required before resubmitting this budget request.';
    END IF;
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status
     AND NEW.status IN ('awaiting_release', 'approved_for_ftf_green', 'hard_copy_submitted', 'budget_released', 'completed')
     AND EXISTS (
       SELECT 1 FROM public.budget_request_files f
       WHERE f.budget_request_id = OLD.id AND f.admin_status IN ('needs_revision', 'rejected_red')
     ) THEN
    RAISE EXCEPTION 'Cannot approve or release a budget request with unresolved document revisions or rejected documents.';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_budget_request_terminal_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Legacy review stages now map to the canonical approval state.
  IF NEW.status IN ('approved_for_ftf_green', 'hard_copy_submitted') THEN
    NEW.status := 'awaiting_release';
  END IF;

  IF TG_OP = 'UPDATE'
     AND OLD.status = 'budget_released'
     AND (
       NEW.status IS DISTINCT FROM OLD.status
       OR NEW.approved_amount IS DISTINCT FROM OLD.approved_amount
       OR NEW.released_amount IS DISTINCT FROM OLD.released_amount
       OR NEW.release_date IS DISTINCT FROM OLD.release_date
     ) THEN
    RAISE EXCEPTION 'Budget Released is the terminal Budget Request state. Release data is immutable; continue financial execution in the liquidation workflow.';
  END IF;

  IF NEW.status = 'completed' THEN
    -- Older seed code still emits `completed`; normalize only fully released
    -- records from the explicitly marked PCYDO sample batch.
    IF coalesce(NEW.is_seeded_sample_data, false)
       AND NEW.seed_batch = 'PCYDO-YORP-2024-2026'
       AND coalesce(NEW.released_amount, 0) > 0
       AND NEW.release_date IS NOT NULL THEN
      NEW.status := 'budget_released';
      RETURN NEW;
    END IF;

    -- Allow unrelated edits to a historical row until it is repaired, but do
    -- not permit inserts or transitions into the legacy terminal value.
    IF TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM NEW.status THEN
      RAISE EXCEPTION 'Completed is not a Budget Request status. Use budget_released; liquidation has its own lifecycle.';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_organization_identity_financial_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'ytrace_identity'
AS $function$
declare _p public.organization_profiles; _outcome text;
begin
 if tg_op='UPDATE' then
   if new.organization_id is distinct from old.organization_id then raise exception 'Historical financial ownership cannot be reassigned.'; end if;
   if old.status::text<>'draft' then return new; end if;
 end if;
 if new.status::text='draft' then return new; end if;
 select * into _p from public.organization_profiles where id=new.organization_id for update;
 if not found or _p.profile_status::text<>'verified' then raise exception 'A verified organization is required before submitting a budget request.'; end if;
 _outcome:=ytrace_identity.assess(_p);
 if _outcome not in ('NO_MATCH','VERIFIED_SEPARATE') then raise exception 'Resolve organization identity with PCYDO before creating a new budget request.'; end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.set_budget_request_fiscal_year()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _default_fy integer;
BEGIN
  IF NEW.fiscal_year IS NULL THEN
    _default_fy := public.get_system_setting_int('budget.default_fiscal_year', EXTRACT(YEAR FROM CURRENT_DATE)::integer);
    NEW.fiscal_year := COALESCE(
      EXTRACT(YEAR FROM NEW.release_date)::integer,
      EXTRACT(YEAR FROM NEW.activity_date)::integer,
      EXTRACT(YEAR FROM NEW.created_at)::integer,
      _default_fy
    );
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_track_document_file_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  submission_row public.document_submissions%ROWTYPE;
  submission_id uuid;
  resource_key text;
BEGIN
  submission_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.submission_id ELSE NEW.submission_id END;
  SELECT * INTO submission_row FROM public.document_submissions WHERE id = submission_id;
  IF FOUND THEN
    resource_key := CASE WHEN submission_row.submission_scope::text = 'renewal' OR submission_row.renewal_id IS NOT NULL THEN 'renewals' ELSE 'registration' END;
    PERFORM public.admin_bump_portal_change_version(resource_key);
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.submission_id IS DISTINCT FROM NEW.submission_id THEN
    SELECT * INTO submission_row FROM public.document_submissions WHERE id = OLD.submission_id;
    IF FOUND THEN
      resource_key := CASE WHEN submission_row.submission_scope::text = 'renewal' OR submission_row.renewal_id IS NOT NULL THEN 'renewals' ELSE 'registration' END;
      PERFORM public.admin_bump_portal_change_version(resource_key);
    END IF;
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

