CREATE OR REPLACE FUNCTION public.generate_organization_reference_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  _year text;
  _sequence int;
  _candidate text;
begin
  -- If reference_id is already explicitly assigned, keep it
  if new.reference_id is not null and trim(new.reference_id) <> '' then
    return new;
  end if;

  _year := to_char(coalesce(new.created_at, now()), 'YYYY');

  -- Atomically increment and lock the year counter
  insert into public.organization_reference_counters (year, last_value)
  values (_year, (
    select coalesce(max(substring(reference_id from 'REG-[0-9]{4}-([0-9]+)')::int), 0) + 1
    from public.organization_profiles
    where reference_id like 'REG-' || _year || '-%'
  ))
  on conflict (year) do update
  set last_value = greatest(
    organization_reference_counters.last_value + 1,
    coalesce((
      select max(substring(reference_id from 'REG-[0-9]{4}-([0-9]+)')::int) + 1
      from public.organization_profiles
      where reference_id like 'REG-' || excluded.year || '-%'
    ), organization_reference_counters.last_value + 1)
  )
  returning last_value into _sequence;

  -- Collision avoidance loop against any manually inserted or anomalous existing IDs
  loop
    _candidate := 'REG-' || _year || '-' || lpad(_sequence::text, 4, '0');
    exit when not exists (
      select 1 from public.organization_profiles where reference_id = _candidate
    );
    _sequence := _sequence + 1;
    update public.organization_reference_counters
    set last_value = _sequence
    where year = _year;
  end loop;

  new.reference_id := _candidate;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.normalize_organization_contact_arrays()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  _cleaned_emails text[] := '{}';
  _cleaned_phones text[] := '{}';
  _item text;
  _norm text;
  _seen_emails text[] := '{}';
  _seen_phones text[] := '{}';
  _primary_email_norm text;
  _primary_phone_norm text;
BEGIN
  -- Normalize primary fields
  NEW.organization_email := nullif(trim(NEW.organization_email), '');
  NEW.contact_number := nullif(trim(NEW.contact_number), '');

  _primary_email_norm := lower(coalesce(NEW.organization_email, ''));
  _primary_phone_norm := regexp_replace(coalesce(NEW.contact_number, ''), '\D', '', 'g');

  IF _primary_email_norm <> '' THEN
    _seen_emails := array_append(_seen_emails, _primary_email_norm);
  END IF;

  IF _primary_phone_norm <> '' THEN
    _seen_phones := array_append(_seen_phones, _primary_phone_norm);
  END IF;

  -- Normalize additional emails
  IF NEW.additional_emails IS NOT NULL THEN
    FOREACH _item IN ARRAY NEW.additional_emails LOOP
      _norm := lower(trim(coalesce(_item, '')));
      IF _norm <> '' AND NOT (_norm = ANY(_seen_emails)) THEN
        _seen_emails := array_append(_seen_emails, _norm);
        _cleaned_emails := array_append(_cleaned_emails, trim(_item));
      END IF;
    END LOOP;
  END IF;
  NEW.additional_emails := _cleaned_emails;

  -- Normalize additional contact numbers
  IF NEW.additional_contact_numbers IS NOT NULL THEN
    FOREACH _item IN ARRAY NEW.additional_contact_numbers LOOP
      _norm := regexp_replace(trim(coalesce(_item, '')), '\D', '', 'g');
      IF _norm <> '' AND NOT (_norm = ANY(_seen_phones)) THEN
        _seen_phones := array_append(_seen_phones, _norm);
        _cleaned_phones := array_append(_cleaned_phones, trim(_item));
      END IF;
    END LOOP;
  END IF;
  NEW.additional_contact_numbers := _cleaned_phones;

  RETURN NEW;
END;
$function$

